"""Generate rtl/npu/npu_pkg.sv from npu/isa.py.

    python -m npu.gen_pkg ../rtl/npu/npu_pkg.sv      (run from sw/)
"""

import sys
from pathlib import Path

from . import isa


def clog2(x: int) -> int:
    return max(1, (x - 1).bit_length())


def render() -> str:
    used = sum(w for _, w, _ in isa.FIELDS)
    lines = [
        "// npu_pkg: NPU machine parameters and instruction format.",
        "// GENERATED by sw/npu/gen_pkg.py from sw/npu/isa.py -- do not edit by hand.",
        "",
        "package npu_pkg;",
        "",
        "    // Shared constants: not every importer uses every one.",
        "    /* verilator lint_off UNUSEDPARAM */",
        f"    localparam int N          = {isa.N};",
        f"    localparam int DATA_W     = {isa.DATA_W};",
        f"    localparam int ACC_W      = {isa.ACC_W};",
        f"    localparam int WORD_W     = N * DATA_W;   // activation / weight word",
        f"    localparam int ACT_DEPTH  = {isa.ACT_DEPTH};",
        f"    localparam int EXT_DEPTH  = {isa.EXT_DEPTH};",
        f"    localparam int WBUF_DEPTH = {isa.WBUF_DEPTH};",
        f"    localparam int PBUF_DEPTH = {isa.PBUF_DEPTH};",
        f"    localparam int PARAM_WORDS = {isa.PARAM_WORDS};",
        f"    localparam int IMEM_DEPTH = {isa.IMEM_DEPTH};",
        f"    localparam int K_MAX      = {isa.K_MAX};",
        f"    localparam int ACT_AW     = {clog2(isa.ACT_DEPTH)};",
        f"    localparam int EXT_AW     = {clog2(isa.EXT_DEPTH)};",
        f"    localparam int WBUF_AW    = {clog2(isa.WBUF_DEPTH)};",
        f"    localparam int PBUF_AW    = {clog2(isa.PBUF_DEPTH)};",
        f"    localparam int IMEM_AW    = {clog2(isa.IMEM_DEPTH)};",
        f"    localparam int K_W        = {clog2(isa.K_MAX + 1)};",
        f"    localparam int INSTR_W    = {isa.INSTR_W};",
        f"    localparam int SHIFT_W    = {isa.SHIFT_W};",
        f"    localparam int PARAM_W    = {isa.PARAM_W};",
        "",
        "    localparam bit RMODE_DOUBLE = 1'b0;   // TFLite CONV_2D rounding",
        "    localparam bit RMODE_SINGLE = 1'b1;   // TFLite FULLY_CONNECTED rounding",
        "    /* verilator lint_on UNUSEDPARAM */",
        "",
        "    typedef enum logic [3:0] {",
    ]
    ops = list(isa.Op)
    for i, op in enumerate(ops):
        lines.append(f"        OP_{op.name:<10s} = 4'h{op.value:X}{',' if i < len(ops) - 1 else ''}")
    lines += ["    } op_e;", "", "    // Fields listed MSB first (isa.py lists them LSB first).",
              "    typedef struct packed {"]
    if isa.INSTR_W - used:
        lines.append(f"        logic [{isa.INSTR_W - used - 1}:0] rsvd;")
    for name, width, signed in reversed(isa.FIELDS):
        if name == "op":
            lines.append("        op_e op;")
        else:
            t = "logic signed" if signed else "logic"
            dim = f" [{width - 1}:0]" if width > 1 else ""
            lines.append(f"        {t}{dim} {name};")
    lines += [
        "    } instr_t;",
        "",
        "    typedef struct packed {",
        "        logic signed [SHIFT_W-1:0] shift;   // >0: left shift, <=0: right shift",
        "        logic signed [31:0]        mult;    // Q31 multiplier",
        "        logic signed [31:0]        bias;    // bias with input zero point folded in",
        "    } param_t;",
        "",
        "endpackage",
        "",
    ]
    return "\n".join(lines)


if __name__ == "__main__":
    out = Path(sys.argv[1] if len(sys.argv) > 1 else "../rtl/npu/npu_pkg.sv")
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(render())
    print(f"wrote {out}")
